define("theme_chronolms/chatbot_toggle", ['jquery'], function($) {
    'use strict';
    var toggleBtn = null, panel = null, closeBtn = null, isOpen = false;
    function openPanel() {
        isOpen = true;
        if (panel) { panel.classList.add('open'); panel.setAttribute('aria-hidden', 'false'); }
        if (toggleBtn) { toggleBtn.classList.add('open'); toggleBtn.setAttribute('aria-expanded', 'true'); }
        var input = panel ? panel.querySelector('input, textarea') : null;
        if (input) setTimeout(function() { input.focus(); }, 200);
    }
    function closePanel() {
        isOpen = false;
        if (panel) { panel.classList.remove('open'); panel.setAttribute('aria-hidden', 'true'); }
        if (toggleBtn) { toggleBtn.classList.remove('open'); toggleBtn.setAttribute('aria-expanded', 'false'); toggleBtn.focus(); }
    }
    function init() {
        toggleBtn = document.getElementById('chronolms-chatbot-toggle');
        panel = document.getElementById('chronolms-chatbot-panel');
        closeBtn = document.getElementById('chatbot-close-btn');
        if (!toggleBtn || !panel) return;
        toggleBtn.addEventListener('click', function() { if (isOpen) closePanel(); else openPanel(); });
        if (closeBtn) closeBtn.addEventListener('click', closePanel);
        document.addEventListener('keydown', function(e) { if (e.key === 'Escape' && isOpen) closePanel(); });
    }
    return { init: init };
});
